def build_part_two(Body):
 specs=[('map','先建立資安知識地圖','Build a security knowledge map',knowledge_map),('authorization','單元一｜White Hat 與合法授權','Unit 1 | White hats and authorization',authorization),('governance','單元二｜ISO、SOC 與營運持續','Unit 2 | ISO, SOC and business continuity',governance),('purge','單元三｜刪除、Purge 與安全清除','Unit 3 | Deletion, purge and sanitization',purge),('encryption','單元四｜加密、區塊、金鑰與分配','Unit 4 | Encryption, blocks, keys and distribution',encryption),('trust','單元五｜Hash、簽章、PKI 與 CA','Unit 5 | Hashes, signatures, PKI and CAs',trust),('integration','九題整合與固定解題法','Integrate the nine references',integration),('recall','八張主動回憶卡','Eight active-recall cards',recall),('checks','五題最終理解檢核','Five final understanding checks',checks)]
 result={'zh':[],'en':[]}
 for id,zh,en,fn in specs:
  body=fn(Body)
  for lang in ['zh','en']:result[lang].append({'id':'p2-'+id,'heading':zh if lang=='zh' else en,'body':body[lang]})
 return result
